  rd: [['キムさんは {韓国人|かんこくじん}です。', 'Kim is Korean.'], ['{学生|がくせい}じゃないです。', 'She isn’t a student.'], ['{会社員|かいしゃいん}です。', 'She’s an office worker.'], ['{英語|えいご}の {先生|せんせい}は {誰|だれ}ですか。', 'Who is the English teacher?']],
