  rd: [['これは {本|ほん}です。', 'This is a book.'], ['それは {辞書|じしょ}です。', 'That is a dictionary.'], ['あれは {新聞|しんぶん}です。', 'That over there is a newspaper.'], ['あれは {辞書|じしょ}じゃないです。', 'That over there isn’t a dictionary.']],
