  tk: [['A', '{今|いま}、{何|なに}を していますか。', 'What are you doing right now?'], ['B', '{日本語|にほんご}を {勉強|べんきょう}しています。', 'I’m studying Japanese.'], ['A', 'どこに {住|す}んでいますか。', 'Where do you live?'], ['B', '{駅|えき}の {近|ちか}くに {住|す}んでいます。', 'I live near the station.']],
