  tk: [['Staff', 'いらっしゃいませ。{何名様|なんめいさま}ですか。', 'Welcome. How many people?'], ['You', '{二人|ふたり}です。', 'Two.'], ['You', 'すみません、おすすめは {何|なん}ですか。', 'Excuse me, what do you recommend?'], ['Staff', 'こちらの {味噌|みそ}ラーメンです。', 'This miso ramen.'], ['You', 'じゃあ、それを {二|ふた}つ ください。', 'Then two of those, please.']],
